from __future__ import annotations

from pathlib import Path
from typing import Any, Sequence


SUPPORTED_SUB_FORMATS = ("srt", "vtt", "ass", "ass-dual")


def _fmt_ts_srt(seconds: float) -> str:
    ms_total = max(0, int(round(float(seconds) * 1000)))
    h = ms_total // 3_600_000
    m = (ms_total % 3_600_000) // 60_000
    s = (ms_total % 60_000) // 1000
    ms = ms_total % 1000
    return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"


def _fmt_ts_vtt(seconds: float) -> str:
    # Same as SRT but with '.' millisecond separator
    return _fmt_ts_srt(seconds).replace(",", ".")


def _fmt_ts_ass(seconds: float) -> str:
    # ASS: H:MM:SS.cs (centiseconds)
    cs_total = max(0, int(round(float(seconds) * 100)))
    h = cs_total // 360_000
    m = (cs_total % 360_000) // 6_000
    s = (cs_total % 6_000) // 100
    cs = cs_total % 100
    return f"{h}:{m:02d}:{s:02d}.{cs:02d}"


def _cue_text(cue: dict[str, Any]) -> str:
    return str(cue.get("text") or "").replace("\r\n", "\n").strip()


def cues_to_srt(cues: Sequence[dict[str, Any]]) -> str:
    lines: list[str] = []
    for i, cue in enumerate(cues, start=1):
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        text = _cue_text(cue)
        lines.append(str(i))
        lines.append(f"{_fmt_ts_srt(start)} --> {_fmt_ts_srt(end)}")
        lines.append(text or " ")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def cues_to_vtt(cues: Sequence[dict[str, Any]]) -> str:
    lines = ["WEBVTT", ""]
    for i, cue in enumerate(cues, start=1):
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        text = _cue_text(cue)
        lines.append(str(i))
        lines.append(f"{_fmt_ts_vtt(start)} --> {_fmt_ts_vtt(end)}")
        lines.append(text or " ")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def cues_to_vtt_karaoke(cues: Sequence[dict[str, Any]]) -> str:
    """
    WebVTT with intra-cue timestamps for word highlighting.

    Format (widely used karaoke-style VTT):
      00:00:00.000 --> 00:00:02.000
      <00:00:00.000><c>Hello</c> <00:00:00.400><c>world</c>
    """
    lines = ["WEBVTT", "", "NOTE Karaoke word timings", ""]
    for i, cue in enumerate(cues, start=1):
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        words = cue.get("words") if isinstance(cue.get("words"), list) else []
        lines.append(str(i))
        lines.append(f"{_fmt_ts_vtt(start)} --> {_fmt_ts_vtt(end)}")
        if words:
            parts: list[str] = []
            for w in words:
                if not isinstance(w, dict):
                    continue
                token = str(w.get("word") or "").strip()
                if not token:
                    continue
                ws = float(w.get("start") if w.get("start") is not None else start)
                # Escape VTT-special: avoid bare < > in token
                safe = token.replace("<", "&lt;").replace(">", "&gt;")
                parts.append(f"<{_fmt_ts_vtt(ws)}><c>{safe}</c>")
            lines.append(" ".join(parts) if parts else (_cue_text(cue) or " "))
        else:
            lines.append(_cue_text(cue) or " ")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def write_karaoke_vtt(
    cues: Sequence[dict[str, Any]],
    output_path: str | Path,
) -> Path:
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path = path.with_suffix(".vtt")
    path.write_text(cues_to_vtt_karaoke(cues), encoding="utf-8")
    return path


def cues_to_ass(cues: Sequence[dict[str, Any]], *, title: str = "Transub") -> str:
    header = (
        "[Script Info]\n"
        f"Title: {title}\n"
        "ScriptType: v4.00+\n"
        "PlayResX: 1920\n"
        "PlayResY: 1080\n"
        "WrapStyle: 0\n"
        "\n"
        "[V4+ Styles]\n"
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, "
        "OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, "
        "ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, "
        "MarginL, MarginR, MarginV, Encoding\n"
        "Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,"
        "0,0,0,0,100,100,0,0,1,2,1,2,40,40,48,1\n"
        "\n"
        "[Events]\n"
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
    )
    events: list[str] = []
    for cue in cues:
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        text = _cue_text(cue).replace("\n", r"\N") or " "
        text = text.replace(",", "，")
        events.append(
            f"Dialogue: 0,{_fmt_ts_ass(start)},{_fmt_ts_ass(end)},Default,,0,0,0,,{text}"
        )
    return header + "\n".join(events) + ("\n" if events else "")


def cues_to_ass_dual(
    source_cues: Sequence[dict[str, Any]],
    zh_cues: Sequence[dict[str, Any]],
    *,
    title: str = "Transub Dual",
) -> str:
    """
    Single ASS with two styles stacked at the bottom (like bilingual SRT):
    Source above ZH via a larger MarginV. Both use Alignment 2 (bottom-center).
    Events are paired by index when lengths match; otherwise each track is emitted fully.
    """
    header = (
        "[Script Info]\n"
        f"Title: {title}\n"
        "ScriptType: v4.00+\n"
        "PlayResX: 1920\n"
        "PlayResY: 1080\n"
        "WrapStyle: 0\n"
        "\n"
        "[V4+ Styles]\n"
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, "
        "OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, "
        "ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, "
        "MarginL, MarginR, MarginV, Encoding\n"
        # Alignment 2 = bottom-center; Source MarginV lifts it above ZH (SRT-like stack)
        "Style: Source,Arial,40,&H00AAAAAA,&H000000FF,&H00000000,&H80000000,"
        "0,0,0,0,100,100,0,0,1,2,1,2,40,40,112,1\n"
        "Style: ZH,Microsoft YaHei,48,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,"
        "0,0,0,0,100,100,0,0,1,2,1,2,40,40,56,1\n"
        "\n"
        "[Events]\n"
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
    )
    events: list[str] = []

    def _line(style: str, cue: dict[str, Any]) -> str:
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        text = _cue_text(cue).replace("\n", r"\N") or " "
        text = text.replace(",", "，")
        return f"Dialogue: 0,{_fmt_ts_ass(start)},{_fmt_ts_ass(end)},{style},,0,0,0,,{text}"

    src = [c for c in source_cues if isinstance(c, dict)]
    zh = [c for c in zh_cues if isinstance(c, dict)]
    if len(src) == len(zh) and src:
        for s, z in zip(src, zh):
            events.append(_line("Source", s))
            events.append(_line("ZH", z))
    else:
        for s in src:
            events.append(_line("Source", s))
        for z in zh:
            events.append(_line("ZH", z))
    return header + "\n".join(events) + ("\n" if events else "")


def write_ass_dual(
    source_cues: Sequence[dict[str, Any]],
    zh_cues: Sequence[dict[str, Any]],
    output_path: str | Path,
) -> Path:
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path = path.with_suffix(".ass")
    path.write_text(
        cues_to_ass_dual(source_cues, zh_cues, title=path.stem),
        encoding="utf-8",
    )
    return path


def render_cues(cues: Sequence[dict[str, Any]], fmt: str = "srt", *, title: str = "Transub") -> str:
    fmt_l = str(fmt or "srt").lower().lstrip(".")
    if fmt_l in ("ass-dual", "dual-ass", "assb"):
        # Single-track render falls back to regular ASS; dual needs write_ass_dual.
        return cues_to_ass(cues, title=title)
    if fmt_l == "vtt":
        return cues_to_vtt(cues)
    if fmt_l == "ass" or fmt_l == "ssa":
        return cues_to_ass(cues, title=title)
    return cues_to_srt(cues)


def write_subtitle(
    cues: Sequence[dict[str, Any]],
    output_path: str | Path,
    fmt: str = "srt",
) -> Path:
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fmt_l = str(fmt or "srt").lower().lstrip(".")
    if fmt_l in ("ass-dual", "dual-ass", "assb"):
        # Without ZH track, write as normal ASS
        fmt_l = "ass"
    if fmt_l not in ("srt", "vtt", "ass"):
        fmt_l = "srt"
    path = path.with_suffix(f".{fmt_l}")
    path.write_text(render_cues(cues, fmt_l, title=path.stem), encoding="utf-8")
    return path


class StreamingSubtitleWriter:
    """
    Incrementally rewrite a subtitle file as cues arrive (Whisper streaming).

    Safe for crash recovery: each flush writes a complete valid file.
    """

    def __init__(self, output_path: str | Path, fmt: str = "srt") -> None:
        self.path = Path(output_path)
        self.fmt = str(fmt or "srt").lower().lstrip(".")
        if self.fmt in ("ass-dual", "dual-ass", "assb"):
            self.fmt = "ass"
        if self.fmt not in ("srt", "vtt", "ass"):
            self.fmt = "srt"
        self.path = self.path.with_suffix(f".{self.fmt}")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._cues: list[dict[str, Any]] = []
        self._dirty = False
        self._flush_every = 8

    def append(self, cue: dict[str, Any]) -> None:
        if not isinstance(cue, dict):
            return
        self._cues.append(dict(cue))
        self._dirty = True
        if len(self._cues) % self._flush_every == 0:
            self.flush()

    def extend(self, cues: Sequence[dict[str, Any]]) -> None:
        for cue in cues:
            self.append(cue)

    def replace_all(self, cues: Sequence[dict[str, Any]]) -> None:
        self._cues = [dict(c) for c in cues if isinstance(c, dict)]
        self._dirty = True
        self.flush()

    def flush(self) -> Path:
        if not self._dirty and self.path.exists():
            return self.path
        self.path.write_text(
            render_cues(self._cues, self.fmt, title=self.path.stem),
            encoding="utf-8",
        )
        self._dirty = False
        return self.path

    def close(self) -> Path:
        return self.flush()

    @property
    def cues(self) -> list[dict[str, Any]]:
        return list(self._cues)
